@dataclass
class DigitalQrOrderingEntity21:
    """Data transfer object for Contactless Table QR Digital Menu and Self-Checkout Web App - Segment 21."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
